responseSchemaJson:
{
  "type": "object",
  "description": "私人助理的核心职责是：理解并直接响应`<LatestNews>`中`用户`的最新内容。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "generatedResult": {
      "type": "object",
      "description": "[响应生成] 包含对`用户`最新内容的响应。",
      "properties": {
        "responseItems": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "私人助理回复内容。"
        }
      },
      "required": [
        "responseItems"
      ],
      "propertyOrdering": [
        "responseItems"
      ]
    },
    "test": {
      "type": "object",
      "description": "[附加测试] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "generatedResult",
    "test"
  ],
  "propertyOrdering": [
    "generatedResult",
    "test"
  ]
}
